import{_ as t}from"./chunks/files.B17OUyrr.js";import{_ as i,c as e,o as r,a2 as o}from"./chunks/framework.CIiVzG-O.js";const m=JSON.parse('{"title":"認識 qDiff","description":"用 qDiff 比較檔案、資料夾與專案改動的簡明介紹。","frontmatter":{"title":"認識 qDiff","description":"用 qDiff 比較檔案、資料夾與專案改動的簡明介紹。"},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1793948370000}'),l={name:"zh-TW/guide/introduction.md"};function s(n,a,d,f,h,c){return r(),e("div",null,[...a[0]||(a[0]=[o('<h1 id="認識-qdiff" tabindex="-1">認識 qDiff <a class="header-anchor" href="#認識-qdiff" aria-label="Permalink to &quot;認識 qDiff&quot;">​</a></h1><p>qDiff 只回答一個問題：<strong>到底改了哪裡？</strong> 把兩個版本並排放好，不同的地方 會用顏色標出來，不用再靠眼睛一行一行對。</p><img src="'+t+'" alt="兩份檔案並排比較" class="guide-shot"><h2 id="大家最常拿來做的三件事" tabindex="-1">大家最常拿來做的三件事 <a class="header-anchor" href="#大家最常拿來做的三件事" aria-label="Permalink to &quot;大家最常拿來做的三件事&quot;">​</a></h2><ul><li><strong>比兩份檔案</strong> —— 初稿與改後稿、改前改後的設定、兩次匯出的內容。一行裡 改動的那幾個字也會單獨標出來。</li><li><strong>比兩個資料夾</strong> —— 工作目錄和它的備份。多了什麼、改了什麼、少了什麼， 一眼就能挑出來，還能順手讓兩邊一致。</li><li><strong>看一個專案資料夾</strong> —— 改動過的檔案排成一列，逐個看差異、提交，不用 在幾個視窗之間來回切。</li></ul><p>圖片、壓縮檔，以及不是純文字的檔案也能比，<a href="./more.html">看看還有哪些用法</a>。</p><h2 id="三步開始" tabindex="-1">三步開始 <a class="header-anchor" href="#三步開始" aria-label="Permalink to &quot;三步開始&quot;">​</a></h2><ol><li>打開 qDiff，把兩個檔案或資料夾拖到視窗裡；也可以從「檔案」選單選擇。</li><li>看帶顏色的行。點側邊的小地圖，或者用「上一處 / 下一處」按鈕逐個查看。</li><li>需要調整就直接改、複製、同步；要給別人看，就把這次比較存成一張圖。</li></ol><div class="tip custom-block"><p class="custom-block-title">不用先設定</p><p>不用註冊帳號，第一次比較之前也沒有什麼要設定的，離線就能用。</p></div><h2 id="免費-也安心" tabindex="-1">免費，也安心 <a class="header-anchor" href="#免費-也安心" aria-label="Permalink to &quot;免費，也安心&quot;">​</a></h2><p>所有比較功能都免費。免費版只在標籤列上多一個小標記，一次性購買即可去掉。 qDiff 只讀取你選擇的檔案，不會把內容發出去，詳見<a href="./../privacy/">隱私政策</a>。</p><h2 id="需要幫忙" tabindex="-1">需要幫忙？ <a class="header-anchor" href="#需要幫忙" aria-label="Permalink to &quot;需要幫忙？&quot;">​</a></h2><p><a href="./faq.html">常見問題</a>裡收了最常被問到的幾件事。如果還有問題， <a href="./support.html">寫信給我們</a>就好。</p>',13)])])}const _=i(l,[["render",s]]);export{m as __pageData,_ as default};
